msgs=[]
for s in lines:
 d=json.loads(s)
 if d.get('type')=='message' and d['message'].get('role')=='user':
  msgs.append(''.join(x.get('text','') for x in d['message'].get('content',[]) if 'text' in x))
print([m[:100] for m in msgs])

import re
pairs=[]
for m in msgs[1:]:
 for i in (1,2):
  im=re.search(rf'Demo pair {i} input \((\d+)x(\d+)\):\n(.*?)(?=\nDemo pair {i} output)',m,re.S)
  om=re.search(rf'Demo pair {i} output \((\d+)x(\d+)\):\n(.*?)(?=\n\nSame instance|\Z)',m,re.S)
  if im and om:
   parse=lambda body:[[int(x) for x in row.split()] for row in body.strip().splitlines()]
   a,b=parse(im.group(3)),parse(om.group(3)); pairs.append((a,b))
print('pairs',len(pairs), [(len(a),len(a[0]),len(b),len(b[0]), mod.transform(a)==b) for a,b in pairs])
